draw:
var dcm = p.d, q = p.q;
var planeY = H * 0.50;
var per = (H * 0.40) / 12.0;      // pixels per cm
var cx = W * 0.5;
var X = function (x) { return cx + x * per; };
var Y = function (y) { return planeY - y * per; };
var Yc = Y(dcm);

ctx.lineWidth = 1;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// field lines traced through the two-charge field
var nLines = 11;
var lines = [];
var i, j;
for (i = 0; i < nLines; i++) {
  var ang = -Math.PI * 0.5 + Math.PI * 0.98 * (i + 0.5) / nLines;
  var px0 = 0.35 * Math.sin(ang), py0 = dcm - 0.35 * Math.cos(ang);
  var pts = [];
  var xx = px0, yy = py0;
  for (j = 0; j < 700; j++) {
    pts.push([X(xx), Y(yy)]);
    if (yy <= 0.02) break;
    var ax = xx, ay = yy - dcm, bx = xx, by = yy + dcm;
    var ra = Math.pow(ax * ax + ay * ay, 1.5);
    var rb = Math.pow(bx * bx + by * by, 1.5);
    if (ra < 1e-6 || rb < 1e-6) break;
    var ex = ax / ra - bx / rb, ey = ay / ra - by / rb;
    var m = Math.sqrt(ex * ex + ey * ey);
    if (m < 1e-9) break;
    xx += 0.12 * ex / m; yy += 0.12 * ey / m;
    if (Math.abs(xx) > (W / per)) break;
  }
  lines.push(pts);
}
ctx.strokeStyle = C.faint;
for (i = 0; i < lines.length; i++) {
  ctx.beginPath();
  for (j = 0; j < lines[i].length; j++) {
    if (j === 0) ctx.moveTo(lines[i][j][0], lines[i][j][1]);
    else ctx.lineTo(lines[i][j][0], lines[i][j][1]);
  }
  ctx.stroke();
}
// markers drifting outward along the lines
var frac = (t * 0.35) % 1;
ctx.fillStyle = C.figure;
for (i = 0; i < lines.length; i++) {
  var k = Math.floor(frac * (lines[i].length - 1));
  ctx.beginPath();
  ctx.arc(lines[i][k][0], lines[i][k][1], 2, 0, Math.PI * 2);
  ctx.fill();
}

// the conductor surface
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(0, planeY); ctx.lineTo(W, planeY); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText("grounded plane, V = 0", 8, planeY - 6);

// induced surface density, drawn downward from the plane
var sig0 = q * 1e4 / (2 * Math.PI * dcm * dcm);   // nC/m^2
var amp = H * 0.30;
ctx.strokeStyle = C.accent;
ctx.beginPath();
for (i = 0; i <= 160; i++) {
  var sx = (-W / 2 + W * i / 160) / per;          // cm
  var f = Math.pow(dcm * dcm / (sx * sx + dcm * dcm), 1.5);
  var yy2 = planeY + 6 + amp * f;
  if (i === 0) ctx.moveTo(X(sx), yy2); else ctx.lineTo(X(sx), yy2);
}
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("induced sigma, negative everywhere", 8, planeY + amp + 26);

// real charge
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, Yc, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("+", cx - 3, Yc + 4);
ctx.fillStyle = C.ink;
ctx.fillText("+q at height d", cx + 12, Yc - 4);

// image charge
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, Yc); ctx.lineTo(cx, Y(-dcm)); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, Y(-dcm), 6, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("image -q, depth d", cx + 12, Y(-dcm) + 4);

// force arrow on the real charge
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cx - 26, Yc); ctx.lineTo(cx - 26, Yc + 22); ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx - 26, Yc + 26); ctx.lineTo(cx - 31, Yc + 17); ctx.lineTo(cx - 21, Yc + 17);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.lineWidth = 1;
ctx.fillText("F", cx - 44, Yc + 16);

var F = 22.475 * q * q / (dcm * dcm);             // microN
var U = -0.22475 * q * q / dcm;                   // microJ
out.note = "d = " + dcm.toFixed(1) + " cm, q = " + q.toFixed(1) + " nC   |   F = " +
  F.toFixed(2) + " uN toward the plane, peak sigma = " + (-sig0).toFixed(0) +
  " nC/m^2, U = " + U.toFixed(3) + " uJ";
